harness=r'''package com.ceru.music.mobile;
import com.getcapacitor.*;import android.net.Uri;import android.content.*;import java.net.*;import java.io.*;
public class StorageHarness {
 static byte[] bytes=new byte[4096];static int networkStatus=200;static int declared=4096;static int connections;
 static void check(boolean value,String s){if(!value)throw new AssertionError(s);System.out.println("PASS "+s);}
 static PluginCall call(String...pairs){PluginCall c=new PluginCall();for(int i=0;i<pairs.length;i+=2)c.args.put(pairs[i],pairs[i+1]);return c;}
 static void await(PluginCall c)throws Exception{if(!c.done.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("native call timeout");}
 static void picked(MusicFoldersPlugin p,PluginCall c,Intent data,int code)throws Exception{var m=MusicFoldersPlugin.class.getDeclaredMethod("folderPicked",PluginCall.class,androidx.activity.result.ActivityResult.class);m.setAccessible(true);m.invoke(p,c,new androidx.activity.result.ActivityResult(code,data));await(c);}
 static PluginCall download(DownloaderPlugin p,String id,String url)throws Exception{PluginCall c=call("id",id,"url",url,"fileName","雨爱.mp3");p.download(c);await(c);return c;}
 static void mainTest(String[] args)throws Exception{
  int sdk=Integer.parseInt(args[1]);android.os.Build.VERSION.SDK_INT=sdk;System.out.println("SDK="+sdk);
  Context.root=new File(args[0]);Context.root.mkdirs();new File(Context.root,"external").mkdirs();new File(Context.root,"internal").mkdirs();
  URL.setURLStreamHandlerFactory(protocol->new URLStreamHandler(){protected URLConnection openConnection(URL u){connections++;return new HttpURLConnection(u){public void disconnect(){}public boolean usingProxy(){return false;}public void connect(){}public int getResponseCode(){return networkStatus;}public long getContentLengthLong(){if(android.os.Build.VERSION.SDK_INT<24)throw new NoSuchMethodError("getContentLengthLong requires API 24");return declared;}public String getHeaderField(String key){return "Content-Length".equalsIgnoreCase(key)?String.valueOf(declared):null;}public InputStream getInputStream(){return new ByteArrayInputStream(bytes);}};}});
  MusicFoldersPlugin folders=new MusicFoldersPlugin();PluginCall get=new PluginCall();folders.get(get);
  if(sdk>=29)check(((JSObject)get.result.get("download")).get("label").equals("内部存储 / Music / CeruMusic"),"default destination is visible public Music/CeruMusic");
  else {check(Boolean.FALSE.equals(((JSObject)get.result.get("download")).get("available")),"API 23-28 requires a chosen SAF download folder instead of broad write permission");Uri legacyTree=Uri.parse("content://com.android.externalstorage.documents/tree/primary%3ALegacyMusic");PluginCall selected=call("mode","download");picked(folders,selected,new Intent("").setData(legacyTree).addFlags(3),-1);check(selected.error==null,"legacy SAF picker validates without API 24 isTreeUri");}
  DownloaderPlugin downloader=new DownloaderPlugin();PluginCall d=download(downloader,"public","https://8.8.8.8/audio.mp3");check(d.error==null&&String.valueOf(d.result.get("path")).startsWith(sdk>=29?"content://media/":"content://com.android.externalstorage.documents/"),"actual downloader returns public MediaStore URI");Uri publicUri=Uri.parse((String)d.result.get("path"));check(java.util.Arrays.equals(java.nio.file.Files.readAllBytes(Context.resolver.files.get(publicUri.toString()).toPath()),bytes),"streamed public file bytes match input");if(sdk>=29)check(Context.resolver.values.get(publicUri.toString()).get("is_pending").equals(0),"shared entry is published only after successful close");
  PluginCall stat=call("path",publicUri.toString());downloader.stat(stat);check(stat.error==null&&((Number)stat.result.get("size")).longValue()==4096,"content download can be verified after completion");
  int managed=Context.resolver.files.size();networkStatus=503;PluginCall bad=download(downloader,"bad","https://8.8.8.8/audio.mp3");check(bad.error.contains("HTTP 503")&&Context.resolver.files.size()==managed,"HTTP failure deletes its pending public entry");networkStatus=200;declared=8192;bad=download(downloader,"partial","https://8.8.8.8/audio.mp3");check(bad.error.contains("不完整")&&Context.resolver.files.size()==managed,"partial stream is rejected and cleaned, never published");declared=4096;
  int requests=connections;bad=download(downloader,"ssrf","http://127.0.0.1/audio.mp3");check(bad.error.contains("局域网")&&connections==requests&&Context.resolver.files.size()==managed,"existing loopback guard runs before transport; target cleanup still works");
  PluginCall scanPick=call("mode","scan");folders.pick(scanPick);check((folders.lastIntent.getFlags()&2)==0,"scan picker requests read-only SAF permission");picked(folders,scanPick,null,0);check(Boolean.TRUE.equals(scanPick.result.get("cancelled")),"cancel leaves scan selection unchanged");
  Uri tree=Uri.parse("content://com.android.externalstorage.documents/tree/primary%3AChosen");scanPick=call("mode","scan");picked(folders,scanPick,new Intent("").setData(tree).addFlags(3),-1);check(scanPick.error==null&&!MusicFoldersPlugin.hasGrant(new Context(),tree,true),"scan selection persists read only even when result also has write flag");
  PluginCall writable=call("mode","download");folders.pick(writable);check((folders.lastIntent.getFlags()&3)==3,"download picker explicitly requests read/write");picked(folders,writable,new Intent("").setData(tree).addFlags(3),-1);check(writable.error==null&&MusicFoldersPlugin.hasGrant(new Context(),tree,true),"chosen download tree retains read/write grant");
  MusicFoldersPlugin reopened=new MusicFoldersPlugin();get=new PluginCall();reopened.get(get);check(((JSObject)get.result.get("download")).get("uri").equals(tree.toString()),"adapter reconstruction retains destination and scan folder settings");
  d=download(downloader,"saf","https://8.8.8.8/audio.mp3");check(d.error==null&&String.valueOf(d.result.get("path")).contains("/document/"),"actual downloader streams into the selected SAF tree");Uri document=Uri.parse((String)d.result.get("path"));check(Context.resolver.files.get(document.toString()).getCanonicalPath().contains("Chosen"),"chosen target physically contains the saved song in contract filesystem");
  File sub=new File(Context.root,"documents/primary/Chosen/Album");sub.mkdirs();java.nio.file.Files.write(new File(sub,"子文件夹.mp3").toPath(),new byte[]{1,2});java.nio.file.Files.write(new File(sub,"说明.txt").toPath(),new byte[]{1});
  Plugin.permission=PermissionState.DENIED;LocalMediaPlugin local=new LocalMediaPlugin();PluginCall scan=call("source","folders");local.scan(scan);await(scan);JSArray tracks=(JSArray)scan.result.get("tracks");check(tracks.size()>=3&&!scan.result.containsKey("error"),"selected folders including children scan without broad media permission");check(tracks.toString().contains("子文件夹")&&!tracks.toString().contains("说明.txt"),"folder scanner recognizes audio, not arbitrary documents");
  File legacy=new File(Context.root,"external/旧版.mp3");java.nio.file.Files.write(legacy.toPath(),new byte[]{9,8,7});PluginCall export=call("path",legacy.getAbsolutePath(),"fileName","旧版.mp3");downloader.exportLegacy(export);await(export);check(export.error==null&&legacy.exists()&&java.util.Arrays.equals(java.nio.file.Files.readAllBytes(Context.resolver.files.get((String)export.result.get("path")).toPath()),new byte[]{9,8,7}),"legacy export verifies a new copy and preserves original file");
  PluginCall foreign=call("path",new File(Context.root,"secret.mp3").getAbsolutePath(),"fileName","x.mp3");downloader.exportLegacy(foreign);await(foreign);check(foreign.error.contains("应用下载目录"),"export cannot read a path outside app-owned Music folders");
  foreign=call("path","content://other/document/private","fileName","x.mp3");downloader.delete(foreign);check(foreign.error.contains("未由本应用"),"delete cannot affect non-managed user documents");
  Context.resolver.grants.clear();bad=download(downloader,"revoked","https://8.8.8.8/audio.mp3");check(bad.error.contains("授权已失效")&&connections==requests+1,"revoked target never silently falls back to another folder");
  scan=call("source","folders");local.scan(scan);await(scan);check(String.valueOf(scan.result.get("error")).contains("授权失效"),"revoked scan grant is reported without hiding other managed downloads");
 }
 public static void main(String[] args){try{mainTest(args);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}'''
